if(!exists('fit_recovery_hurdle'))library(creditratingsystem)
lw_target<-list(event='residual_terminal_loss_fraction',horizon_role='TIMING_REPORTING_REFERENCE',horizon=365,time_unit='days',probability_measure='PHYSICAL',conditioning='given_default',currency='EUR')
lw_train<-list(data_fingerprint='hand',split_id='train',known_at='2024-12-31',data_origin='SYNTHETIC',workout_population='open_and_closed_defaulted_landmarks')
lw_stage<-list(payout_definition='RESIDUAL_TERMINAL_GROSS_RECOVERY_OR_CURE_VALUE',cashflow_pattern='SINGLE_TERMINAL_PAYOUT_AFTER_REFERENCE',timing_outcome_independence='CONDITIONAL_ON_REFERENCE_COVARIATES',positive_distribution='lognormal',cashflow_completeness='COMPLETE_THROUGH_OBSERVATION_END',payout_horizon='ULTIMATE',timing_distribution='weibull',cure_residual_value_ratio=1,landmark_definition='Account enters residual terminal settlement stage')
lw_near<-function(x,y)stopifnot(isTRUE(all.equal(as.numeric(unlist(x)),as.numeric(y),tolerance=1e-9)))
lw_error<-function(code,expr){e<-tryCatch({force(expr);NULL},error=identity);stopifnot(inherits(e,'creditratingsystem_error'),identical(e$code,code))}
lw_episode<-function(eid='a',closed=FALSE,days=10,cured=0){resolution<-as.character(as.Date('2024-01-01')+days);list(episode_id=eid,default_date='2023-12-01',default_known_at='2023-12-01',reference_date='2024-01-01',reference_known_at='2024-01-01',features_observed_at='2024-01-01',features_known_at='2024-01-01',currency='EUR',ead_at_default=100,residual_exposure_at_reference=80,observation_end='2024-04-01',resolution_date=if(closed)resolution else NULL,resolution_known_at=if(closed)resolution else NULL,cured=cured,cure_value=if(cured==1)80 else 0)}
lw_flow<-function(eid,amount,when,kind='RECOVERY',id=eid)list(episode_id=eid,cashflow_id=id,cashflow_date=when,known_at=when,currency='EUR',kind=kind,amount=amount)
lw_rows<-lapply(0:7,function(i)lw_episode(as.character(i),i<6,10+5*i,as.numeric(i<2)))
lw_flows<-list(lw_flow('4',80*exp(-1),lw_rows[[5]]$resolution_date),lw_flow('5',80*exp(1),lw_rows[[6]]$resolution_date))
lw_fit<-fit_recovery_hurdle(lw_rows,lw_flows,matrix(numeric(),8,0),character(),lw_stage,lw_target,lw_train,'h','1','EUR')
lw_p<-predict_lgd(lw_fit,matrix(numeric(),1,0),character(),lw_target,'given_default',quantile_levels=c(.1,.4,.9))$value
lw_near(lw_p$cure_probability,1/3);lw_near(lw_p$positive_noncure_probability,1/3);lw_near(lw_p$conditional_positive_log_mean,0);lw_near(lw_p$conditional_positive_log_variance,1);lw_near(lw_p$mean_lgd,1-(1+exp(.5))/3);lw_near(lw_p$quantiles[[1]][2:3],c(0,1));stopifnot(lw_fit$model$diagnostics$censored_count==2)
lw_model<-lw_fit$model;lw_model$training$known_at<-'2023-12-01';for(key in c('cure_gate','positive_gate','timing_model'))lw_model$parameters[[key]]$training$known_at<-'2023-12-01';lw_model$parameters$timing_model$parameters$coefficients<-list(log(10));lw_model$parameters$timing_model$parameters$log_time_scale<-1;lw_model$parameters$timing_model$parameters$support_end<-1000
lw_valuation<-function(tail=NULL){dates<-c('2023-12-15','2024-01-11','2024-01-21','2024-01-26','2024-02-01');list(episode_id='a',discount_curve=list(anchor_date='2023-12-01',known_at='2024-01-11',discount_basis='user economic',points=lapply(seq_along(dates),function(i)list(cashflow_date=dates[i],discount_factor=c(1,.9,.8,.7,.6)[i]))),fx_contract=list(reporting_currency='EUR',known_at='2024-01-11',conversion_basis='cashflow_date',rates=lapply(dates,function(d)list(currency='EUR',date=d,rate=1))),future_resolution_dates=as.list(c('2024-01-21','2024-02-01')),resolution_time_convention='RIGHT_ENDPOINT',tail_discount_factor=tail,tail_assumption_reference=if(is.null(tail))NULL else 'independent flat average',unmodeled_future_costs_assumption='NONE_BEYOND_SUPPLIED')}
lw_value<-function(rows=list(lw_episode()),flows=list(lw_flow('a',10,'2023-12-15')),tail=NULL,costs=list(),model=lw_model)estimate_open_workout_lgd(rows,flows,model,matrix(numeric(),1,0),list(lw_valuation(tail)),costs,character(),lw_target,lw_stage,'2024-01-11','EUR','parametric')$value$episodes[[1]]
r<-lw_value();mean_value<-80*(1+exp(.5))/3;expected<-mean_value*((1-exp(-1))*.8+(exp(-1)-exp(-2.1))*.6);lw_near(r$expected_discounted_future_terminal_value_within_grid,expected);lw_near(r$known_discounted_net_cashflows,10);lw_near(r$unresolved_probability,exp(-2.1));stopifnot(is.null(r$expected_final_lgd));lw_near(r$expected_loss_within_grid,90-expected);full<-lw_value(tail=.4);lw_near(full$expected_final_lgd,(90-expected-mean_value*exp(-2.1)*.4)/100)
cost<-lw_flow('a',5,'2024-01-26','DIRECT_COST','cost');cost$known_at<-'2024-01-10';r<-lw_value(tail=.4,costs=list(cost));lw_near(r$expected_final_loss-full$expected_final_loss,3.5)
r<-lw_value(rows=list(lw_episode(closed=TRUE,cured=1)));stopifnot(r$status=='OBSERVED_CLOSED');lw_near(r$expected_final_lgd,.18)
stopifnot(lw_value(rows=list(lw_episode(closed=TRUE,days=20,cured=1)))$status=='UNRESOLVED_TAIL_VALUE');lw_error('RECOVERY_STAGE',lw_value(flows=list(lw_flow('a',1,'2024-01-05'))));row<-lw_episode();row$ead_at_default<-0;r<-lw_value(rows=list(row),tail=.4);stopifnot(is.null(r$expected_final_lgd),!is.null(r$expected_final_loss));bad<-lw_model;bad$parameters$stage_spec$cashflow_pattern<-'TOTAL_WORKOUT';lw_error('RECOVERY_STAGE',lw_value(model=bad))
p<-predict_lgd(lw_fit,matrix(numeric(),1,0),character(),lw_target,'given_default',quantile_levels=c(.1,.4,.6,.9))$value;stopifnot(p$payout_horizon=='ULTIMATE');lw_near(p$quantiles[[1]],c(1-exp(qnorm(.3,lower.tail=FALSE)),0,1-exp(qnorm(.8,lower.tail=FALSE)),1));bad<-lw_fit$model;bad$target$horizon_role<-NULL;lw_error('TARGET_MISMATCH',predict_lgd(bad,matrix(numeric(),1,0),character(),bad$target,'given_default'));row<-lw_episode();row$features_known_at<-'2024-01-02';lw_error('RECOVERY_DATE',lw_value(rows=list(row)));bad<-lw_model;bad$parameters$amount_regression<-list();lw_error('INVALID_MODEL',lw_value(model=bad));bad<-lw_model;bad$parameters$stage_spec$cashflow_completeness<-NULL;lw_error('RECOVERY_STAGE',lw_value(model=bad));future<-lw_flow('a',999,'2024-02-15',id='unknown');future$known_at<-'2024-02-16';r<-lw_value(flows=list(lw_flow('a',10,'2023-12-15'),future));lw_near(r$known_discounted_net_cashflows,10);stopifnot(identical(r$excluded_cashflows,list('unknown')));duplicate<-lw_flow('a',5,'2024-01-26','DIRECT_COST');duplicate$known_at<-'2024-01-10';lw_error('RECOVERY_CONTRACT',lw_value(costs=list(duplicate)))
